INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Liegt 10.0.0.1 im Bereich von Klasse A?', 2, '[{"text": "Ja", "correct": true, "because": "1.0.0.0 - 127.255.255.255"}, {"text": "Nein", "correct": false, "because": "Passt in Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich gehört zu Klasse C?', 3, '[{"text": "192.0.0.0 - 223.255.255.255", "correct": true, "because": "Klasse-C-Definition"}, {"text": "128.0.0.0 - 191.255.255.255", "correct": false, "because": "Klasse B"}, {"text": "224.0.0.0 - 239.255.255.255", "correct": false, "because": "Klasse D"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse B startet bei 128. b) Klasse E endet bei 255.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse E bis 254"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bereichsbestimmung?', 4, '[{"text": "Erstes Oktett", "correct": false, "because": "Definiert Klasse"}, {"text": "Bitmuster", "correct": false, "because": "Bestimmt Bereich"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 127.0.0.1 zu Klasse A gehört?', 2, '[{"text": "Ja", "correct": true, "because": "Im Bereich 1-127"}, {"text": "Nein", "correct": false, "because": "Passt in Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse liegt außerhalb von Klasse B?', 3, '[{"text": "192.168.1.1", "correct": true, "because": "Klasse C"}, {"text": "172.16.0.1", "correct": false, "because": "128-191"}, {"text": "130.0.0.1", "correct": false, "because": "Klasse B"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche gehören zu Klasse D?', 5, '[{"text": "224.0.0.0 - 239.255.255.255", "correct": true, "because": "Multicast"}, {"text": "240.0.0.0 - 254.255.255.255", "correct": false, "because": "Klasse E"}, {"text": "192.0.0.0 - 223.255.255.255", "correct": false, "because": "Klasse C"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Klasse A geht bis 127. b) Klasse C startet bei 223. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse C ab 192"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Bereichsbestimmung?', 4, '[{"text": "Erstes Oktett", "correct": false, "because": "Definiert Klasse"}, {"text": "Bitanzahl", "correct": false, "because": "Bestimmt Struktur"}, {"text": "Betriebssystem", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beginnt Klasse D bei 224?', 2, '[{"text": "Ja", "correct": true, "because": "224-239 ist Multicast"}, {"text": "Nein", "correct": false, "because": "Korrekter Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist für Klasse E reserviert?', 4, '[{"text": "240.0.0.0 - 254.255.255.255", "correct": true, "because": "Experimentell"}, {"text": "224.0.0.0 - 239.255.255.255", "correct": false, "because": "Klasse D"}, {"text": "1.0.0.0 - 127.255.255.255", "correct": false, "because": "Klasse A"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 0.0.0.0 zu Klasse A gehört. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Spezielle Adresse, nicht 1-127"}, {"text": "Ja", "correct": false, "because": "Außerhalb Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Bereichsprüfung?', 3, '[{"text": "Erstes Oktett", "correct": true, "because": "Bestimmt Klasse"}, {"text": "Letztes Oktett", "correct": false, "because": "Host-spezifisch"}, {"text": "Zufällige Bits", "correct": false, "because": "Struktur entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse C endet bei 223. b) Klasse B geht bis 191.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Korrekte Bereiche"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen gehören zu Klasse A?', 5, '[{"text": "10.0.0.1", "correct": true, "because": "1-127"}, {"text": "127.0.0.1", "correct": true, "because": "Loopback in A"}, {"text": "192.168.0.1", "correct": false, "because": "Klasse C"}, {"text": "172.16.0.1", "correct": false, "because": "Klasse B"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bereichsbestimmung unwichtig?', 3, '[{"text": "Erstes Oktett", "correct": false, "because": "Definiert Klasse"}, {"text": "Klassengrenze", "correct": false, "because": "Bestimmt Bereich"}, {"text": "Schriftart", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Liegt 223.0.0.1 in Klasse C?', 3, '[{"text": "Ja", "correct": true, "because": "192-223"}, {"text": "Nein", "correct": false, "because": "Passt in Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 240.0.0.1 zu Klasse E gehört?', 2, '[{"text": "Ja", "correct": true, "because": "240-254"}, {"text": "Nein", "correct": false, "because": "Korrekter Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse gehört nicht zu Klasse B?', 4, '[{"text": "191.255.255.255", "correct": false, "because": "128-191"}, {"text": "172.16.0.1", "correct": false, "because": "Klasse B"}, {"text": "224.0.0.1", "correct": true, "because": "Klasse D"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse hat den Bereich 128.0.0.0 - 191.255.255.255?', 3, '[{"text": "Klasse B", "correct": true, "because": "Korrekte Definition"}, {"text": "Klasse A", "correct": false, "because": "1-127"}, {"text": "Klasse C", "correct": false, "because": "192-223"}]');
